import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import BASE_URL from '../../config/apiConfig';
import styles from './BookingModal.module.css';

const BookingModal = ({ counsellorId, onClose }) => {
  const [step, setStep] = useState(1);
  const [slots, setSlots] = useState([]);
  const [selectedSlot, setSelectedSlot] = useState(null);
  const [loading, setLoading] = useState(true);
  const [paymentLoading, setPaymentLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchSlots();
  }, [counsellorId]);

  const fetchSlots = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('accessToken');
      const response = await axios.get(`${BASE_URL}/user/appointments/slots?counsellor_id=${counsellorId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSlots(response.data.slots || []);
      setError(null);
    } catch (err) {
      console.error("Failed to fetch slots", err);
      setError("Failed to load available slots.");
    } finally {
      setLoading(false);
    }
  };

  const handleSelectSlot = (slot) => {
    setSelectedSlot(slot);
    setStep(2); // Move to payment
  };

  const handlePayment = async () => {
    try {
      setPaymentLoading(true);
      const token = localStorage.getItem('accessToken');

      // Since there's no actual Stripe connected, we just call the book endpoint directly.
      await axios.post(`${BASE_URL}/user/appointments`, {
        counsellor_id: counsellorId,
        availability_slot_id: selectedSlot.availability_slot_id,
        reason: 'General Consultation'
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      toast.success('Payment successful! Appointment booked.');
      onClose();
    } catch (err) {
      console.error("Booking failed", err);
      toast.error(err.response?.data?.detail || "Failed to complete booking.");
      setPaymentLoading(false);
    }
  };

  return (
    <div className={styles.modalOverlay}>
      <div className={styles.modalContent}>
        {step === 1 && (
          <>
            <h3 className={styles.title}>Select an Appointment Time</h3>
            <p className={styles.subtitle}>Choose an available slot for this professional.</p>

            {loading ? (
              <p>Loading slots...</p>
            ) : error ? (
              <div className={styles.errorMessage}>{error}</div>
            ) : slots.length === 0 ? (
              <p>This counsellor currently has no open slots available.</p>
            ) : (
              <div className={styles.slotsGrid}>
                {slots.map((slot) => {
                  const dateObj = new Date(slot.start_time);
                  const dateStr = dateObj.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });
                  const timeStr = dateObj.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });

                  return (
                    <button 
                      key={slot.availability_slot_id} 
                      className={styles.slotButton}
                      onClick={() => handleSelectSlot(slot)}
                    >
                      <span className={styles.slotDate}>{dateStr}</span>
                      <span className={styles.slotTime}>{timeStr}</span>
                    </button>
                  );
                })}
              </div>
            )}

            <div className={styles.actions}>
              <button className={styles.cancelBtn} onClick={onClose}>Close</button>
            </div>
          </>
        )}

        {step === 2 && selectedSlot && (
          <>
            <h3 className={styles.title}>Confirm & Pay</h3>
            <p className={styles.subtitle}>Review your appointment details.</p>

            <div className={styles.paymentDetails}>
              <div className={styles.paymentRow}>
                <span>Date:</span>
                <strong>{new Date(selectedSlot.start_time).toLocaleDateString()}</strong>
              </div>
              <div className={styles.paymentRow}>
                <span>Time:</span>
                <strong>{new Date(selectedSlot.start_time).toLocaleTimeString()}</strong>
              </div>
              <div className={styles.paymentTotal}>
                <span>Total Due:</span>
                <span>₹500.00</span>
              </div>
            </div>

            <div className={styles.actions}>
              <button 
                className={styles.cancelBtn} 
                onClick={() => setStep(1)}
                disabled={paymentLoading}
              >
                Back
              </button>
              <button 
                className={styles.payBtn} 
                onClick={handlePayment}
                disabled={paymentLoading}
              >
                {paymentLoading ? 'Processing...' : 'Pay Now'}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default BookingModal;

// src/components/chat/ChatSidebar.jsx
// Production chat sidebar listing user-counsellor conversations.

import React, { useEffect, useState } from 'react';
import axios from 'axios';
import styles from './ChatSidebar.module.css';
import BASE_URL from '../../config/apiConfig';

const ChatSidebar = ({ selectedRoom, setSelectedRoom, preSelectedRoomId }) => {
  const [rooms, setRooms] = useState([]);
  const token = localStorage.getItem('accessToken');

  // Decode user_id from JWT
  const getUserId = () => {
    try {
      const payload = JSON.parse(atob(token.split('.')[1]));
      return payload.sub;
    } catch { return null; }
  };

  const userId = getUserId();

  useEffect(() => {
    const fetchRooms = async () => {
      try {
        const res = await axios.get(`${BASE_URL}/chat/rooms?user_id=${userId}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        const fetchedRooms = res.data.rooms || [];
        setRooms(fetchedRooms);
        if (preSelectedRoomId && !selectedRoom) {
          const roomToSelect = fetchedRooms.find(r => r.room_id === preSelectedRoomId);
          if (roomToSelect) {
            setSelectedRoom(roomToSelect);
          }
        }
      } catch (err) {
        console.error('Error fetching chat rooms:', err);
      }
    };

    if (userId) fetchRooms();
    // Poll for new rooms every 30s
    const interval = setInterval(fetchRooms, 30000);
    return () => clearInterval(interval);
  }, [userId, token]);

  return (
    <>
      <ul className={styles.chatList}>
        {rooms.length === 0 && (
          <li className={styles.chatItem} style={{ opacity: 0.5, cursor: 'default' }}>
            No conversations yet
          </li>
        )}
        {rooms.map(room => (
          <li
            key={room.room_id}
            className={`${styles.chatItem} ${selectedRoom?.room_id === room.room_id ? styles.active : ''}`}
            onClick={() => {
              setRooms(prev => prev.map(r => r.room_id === room.room_id ? {...r, unread_count: 0} : r));
              setSelectedRoom(room);
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', width: '100%' }}>
              <div>
                <strong>{room.other_user_name || room.room_id.replace('chat_', '').replace(userId, '').replace('_', '')}</strong>
                <p style={{ fontSize: 12, color: '#888', margin: '4px 0 0' }}>
                  {room.last_message || 'Start a conversation'}
                </p>
              </div>
              {room.unread_count > 0 && (
                <span style={{
                  background: '#003fdd', color: 'white', borderRadius: '50%',
                  width: 20, height: 20, display: 'flex', alignItems: 'center',
                  justifyContent: 'center', fontSize: 11, fontWeight: 'bold', flexShrink: 0
                }}>
                  {room.unread_count}
                </span>
              )}
            </div>
          </li>
        ))}
      </ul>
    </>
  );
};

export default ChatSidebar;

// src/components/chat/ChatWindow.jsx
// Production WebRTC-based real-time chat window.

import React, { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';
import styles from './ChatWindow.module.css';
import ChatInput from './ChatInput';
import ChatMessage from './ChatMessage';
import BASE_URL from '../../config/apiConfig';
import { FaPhone, FaVideo, FaEllipsisV, FaCircle } from 'react-icons/fa';
import { toast } from 'react-toastify';

const WS_BASE = BASE_URL.replace('http', 'ws').replace('/api/v1', '');

const ChatWindow = ({ room, currentUserId }) => {
  const [messages, setMessages] = useState([]);
  const [onlineUsers, setOnlineUsers] = useState([]);
  const [isTyping, setIsTyping] = useState(false);
  const [typingUser, setTypingUser] = useState(null);

  const wsRef = useRef(null);
  const pcRef = useRef(null);
  const dataChannelRef = useRef(null);
  const messagesEndRef = useRef(null);
  const typingTimeoutRef = useRef(null);

  const handleReceiveMessage = useCallback((event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'message') {
          setMessages(prev => {
              if (prev.some(m => m.message_id === data.message.message_id)) return prev;
              return [...prev, data.message];
          });
      } else if (data.type === 'typing') {
          setTypingUser(data.user_id);
          setIsTyping(data.is_typing);
          if (data.is_typing) {
              clearTimeout(typingTimeoutRef.current);
              typingTimeoutRef.current = setTimeout(() => setIsTyping(false), 2000);
          }
      }
  }, []);

  const sendReadReceipts = useCallback((msgs) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
        setMessages(prev => {
            const currentMsgs = msgs || prev;
            const unreads = currentMsgs.filter(m => m.sender_id !== currentUserId && !m.is_read);
            if (unreads.length === 0) return prev;

            unreads.forEach(m => wsRef.current.send(JSON.stringify({ type: 'read', message_id: m.message_id })));

            return prev.map(m => unreads.some(u => u.message_id === m.message_id) ? { ...m, is_read: true } : m);
        });
    }
  }, [currentUserId]);

  useEffect(() => {
    sendReadReceipts(messages);
  }, [messages, sendReadReceipts]);

  const initializePeerConnection = useCallback(() => {
    if (pcRef.current) return pcRef.current;

    const pc = new RTCPeerConnection({
        iceServers: [{ urls: 'stun:stun.l.google.com:19302' }]
    });

    pc.onicecandidate = (event) => {
        if (event.candidate && wsRef.current?.readyState === WebSocket.OPEN) {
            wsRef.current.send(JSON.stringify({
                type: 'ice_candidate',
                payload: event.candidate
            }));
        }
    };

    pc.ondatachannel = (event) => {
        const receiveChannel = event.channel;
        receiveChannel.onmessage = handleReceiveMessage;
        dataChannelRef.current = receiveChannel;
    };

    pcRef.current = pc;
    return pc;
  }, [handleReceiveMessage]);

  const initiateCall = useCallback(async () => {
      const pc = initializePeerConnection();
      if (dataChannelRef.current) return; // already initiated

      const sendChannel = pc.createDataChannel('text-chat');
      sendChannel.onmessage = handleReceiveMessage;
      dataChannelRef.current = sendChannel;

      const offer = await pc.createOffer();
      await pc.setLocalDescription(offer);

      if (wsRef.current?.readyState === WebSocket.OPEN) {
          wsRef.current.send(JSON.stringify({ type: 'sdp_offer', payload: offer }));
      }
  }, [initializePeerConnection, handleReceiveMessage]);

  // Connect WebSocket & WebRTC Signaling
  useEffect(() => {
    if (!room?.room_id) return;

    const token = localStorage.getItem('accessToken');

    // Fetch message history first
    fetch(`${BASE_URL}/chat/rooms/${room.room_id}/messages?limit=100`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setMessages(data.messages || []))
      .catch(console.error);

    // Open WebSocket for signaling
    const ws = new WebSocket(`${WS_BASE}/chat/${room.room_id}?token=${token}`);
    wsRef.current = ws;

    ws.onopen = () => {
        sendReadReceipts();
    };

    ws.onmessage = async (event) => {
      const data = JSON.parse(event.data);

      switch (data.type) {
        case 'online': {
          setOnlineUsers(data.users || []);
          // WebRTC initiator logic: Alphabetically smaller user ID initiates
          const otherUser = data.users.find(u => u.user_id !== currentUserId);
          if (otherUser && currentUserId < otherUser.user_id) {
              initiateCall();
          }
          break;
        }
        case 'sdp_offer': {
          const pc = initializePeerConnection();
          await pc.setRemoteDescription(new RTCSessionDescription(data.payload));
          const answer = await pc.createAnswer();
          await pc.setLocalDescription(answer);
          ws.send(JSON.stringify({ type: 'sdp_answer', payload: answer }));
          break;
        }
        case 'sdp_answer':
          if (pcRef.current) {
              await pcRef.current.setRemoteDescription(new RTCSessionDescription(data.payload));
          }
          break;
        case 'ice_candidate':
          if (pcRef.current && pcRef.current.remoteDescription) {
              try {
                await pcRef.current.addIceCandidate(new RTCIceCandidate(data.payload));
              } catch(e) { console.error("Error adding ice candidate", e); }
          }
          break;
        case 'message':
          // Catch old WS messages just in case
          setMessages(prev => {
              if (prev.some(m => m.message_id === data.message_id)) return prev;
              return [...prev, data];
          });
          break;
        case 'typing':
          if (data.user_id !== currentUserId) {
            setTypingUser(data.user_id);
            setIsTyping(data.is_typing);
          }
          break;
        case 'read_receipt':
          setMessages(prev => prev.map(m =>
            m.message_id === data.message_id ? { ...m, is_read: true } : m
          ));
          break;
      }
    };

    ws.onerror = (err) => console.error('[WS Error]', err);
    ws.onclose = () => console.log('[WS] Disconnected from', room.room_id);

    return () => {
      ws.close();
      if (pcRef.current) {
          pcRef.current.close();
          pcRef.current = null;
      }
    };
  }, [room?.room_id, currentUserId, initializePeerConnection, initiateCall]);

  // Auto-scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = useCallback(async (text) => {
    const userType = localStorage.getItem('userType');
    const token = localStorage.getItem('accessToken');

    // 1. Send via WebRTC if possible
    if (dataChannelRef.current?.readyState === 'open') {
        const tempMsg = {
            message_id: Date.now().toString(),
            sender_id: currentUserId,
            sender_type: userType,
            content: text,
            created_at: new Date().toISOString(),
            is_read: false
        };
        setMessages(prev => [...prev, tempMsg]);

        dataChannelRef.current.send(JSON.stringify({
            type: 'message',
            message: tempMsg
        }));

        // Fire & forget REST to persist
        axios.post(`${BASE_URL}/chat/rooms/${room.room_id}/messages?user_id=${currentUserId}`, {
            message_id: tempMsg.message_id,
            content: text,
            sender_type: userType,
            message_type: 'text'
        }, { headers: { Authorization: `Bearer ${token}` } }).catch(console.error);

    } else {
        // Fallback: Send only via WebSocket, which persists and broadcasts it back to us
        if (wsRef.current?.readyState === WebSocket.OPEN) {
             wsRef.current.send(JSON.stringify({ type: 'message', content: text }));
        } else {
             toast.error("Not connected to chat server");
        }
    }
  }, [room, currentUserId]);

  const handleTyping = useCallback(() => {
    const typingData = { type: 'typing', user_id: currentUserId, is_typing: true };
    if (dataChannelRef.current?.readyState === 'open') {
        dataChannelRef.current.send(JSON.stringify(typingData));
    } else if (wsRef.current?.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify(typingData));
    }

    clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      const stopTypingData = { type: 'typing', user_id: currentUserId, is_typing: false };
      if (dataChannelRef.current?.readyState === 'open') {
          dataChannelRef.current.send(JSON.stringify(stopTypingData));
      } else if (wsRef.current?.readyState === WebSocket.OPEN) {
          wsRef.current.send(JSON.stringify(stopTypingData));
      }
    }, 2000);
  }, [currentUserId]);

  const otherUser = room?.other_user_name || room?.room_id?.split('_').pop() || 'Counsellor';
  const isOtherOnline = onlineUsers.some(u => u.user_id !== currentUserId);

  return (
    <div className={styles.chatWindowContainer}>
      <header className={styles.chatHeader}>
        <div className={styles.headerInfo}>
          <div className={styles.botAvatar}>
            {room?.other_user_pic ? (
              <img src={room.other_user_pic} alt={otherUser} style={{ width: '100%', height: '100%', borderRadius: '50%', objectFit: 'cover' }} />
            ) : (
              <span><span className="material-symbols-outlined text-lg">person</span></span>
            )}
          </div>
          <div className={styles.headerText}>
            <h2>{otherUser}</h2>
            <span className={styles.activeStatus}>
              <FaCircle style={{ color: isOtherOnline ? '#28a745' : '#999', fontSize: 8, marginRight: 5 }} />
              {isOtherOnline ? 'Online' : 'Offline'}
            </span>
          </div>
        </div>
        <div style={{ display: 'flex', gap: 12 }}>
          <button className={styles.iconBtn} title="Audio Call"><FaPhone /></button>
          <button className={styles.iconBtn} title="Video Call"><FaVideo /></button>
          <button className={styles.iconBtn}><FaEllipsisV /></button>
        </div>
      </header>

      {isTyping && typingUser && (
        <div className={styles.warningBanner} style={{ backgroundColor: 'var(--color-surface-container-low)', padding: '8px 24px', borderBottom: 'var(--border-width) solid var(--border-color)' }}>
          <span style={{ fontSize: '13px', color: 'var(--color-on-surface-variant)', fontStyle: 'italic', fontWeight: 600 }}>typing...</span>
        </div>
      )}

      <div className={styles.chatMessages}>
        {messages.map((msg, idx) => (
          <ChatMessage
            key={msg.message_id || idx}
            message={{
              sender: msg.sender_id === currentUserId ? 'user' : 'other',
              text: msg.content,
              timestamp: msg.created_at,
              is_read: msg.is_read
            }}
          />
        ))}
        <div ref={messagesEndRef} />
      </div>

      <ChatInput onSend={handleSend} onTyping={handleTyping} />
    </div>
  );
};

export default ChatWindow;

// src/components/counsellors/Appointments.jsx

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import styles from '../normal_users/Appointments.module.css';
import axios from 'axios';
import BASE_URL from '../../config/apiConfig';
import { toast } from 'react-toastify';

const Appointments = () => {
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  
  const token = localStorage.getItem('accessToken');

  useEffect(() => {
    fetchAppointments();
  }, []);

  const fetchAppointments = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${BASE_URL}/counsellor/appointments`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setAppointments(res.data.appointments || []);
    } catch (err) {
      console.error('Error fetching appointments:', err);
      toast.error('Failed to fetch appointments');
    } finally {
      setLoading(false);
    }
  };

  const cancelAppointment = async (appointmentId) => {
    if (!window.confirm("Are you sure you want to cancel this appointment?")) return;
    
    try {
      setLoading(true);
      await axios.patch(`${BASE_URL}/counsellor/appointments/cancel/${appointmentId}`, null, {
        headers: { Authorization: `Bearer ${token}` },
        params: { reason: "Counsellor cancelled" }
      });
      toast.success('Appointment cancelled successfully!');
      fetchAppointments();
    } catch (err) {
      console.error('Error cancelling appointment:', err);
      toast.error('Failed to cancel appointment');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <h2 className={styles.heading}>My Appointments</h2>

      {loading && <p className={styles.placeholderText}>Loading...</p>}

      {!loading && (
        <>
          {appointments.length > 0 ? (
            <div className={styles.cardGrid}>
              {appointments.map((appt) => (
                <div key={appt.appointment_id} className={styles.card}>
                  <h4 style={{marginBottom: 10, color: '#003fdd'}}>With Patient: {appt.user?.name || 'Unknown'}</h4>
                  <p><strong>Status:</strong> <span style={{color: appptStatusColor(appt.status)}}>{appt.status}</span></p>
                  <p><strong>Scheduled:</strong> {new Date(appt.session?.session_scheduled_at).toLocaleString()}</p>
                  
                  {(appt.status === 'scheduled' || appt.status === 'confirmed') && (
                    <div style={{ marginTop: 15, display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                      <button 
                        onClick={() => navigate(`/counselling-session/${appt.session?.session_id}`)}
                        style={{ backgroundColor: '#003fdd', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer' }}
                      >
                        Join Call
                      </button>
                      <button 
                        onClick={() => {
                          const roomId = `chat_${appt.counsellor?.user_id}_${appt.user?.user_id}`;
                          navigate('/chat', { state: { selectedRoomId: roomId } });
                        }}
                        style={{ backgroundColor: '#28a745', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer' }}
                      >
                        Message
                      </button>
                    </div>
                  )}

                  {appt.status !== 'cancelled' && appt.status !== 'completed' && (
                    <button 
                      onClick={() => cancelAppointment(appt.appointment_id)}
                      style={{marginTop: 15, backgroundColor: '#dc3545', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer'}}
                    >
                      Cancel Appointment
                    </button>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <p className={styles.placeholderText}>You have no scheduled appointments yet.</p>
          )}
        </>
      )}
    </div>
  );
};

const appptStatusColor = (status) => {
  switch (status?.toLowerCase()) {
    case 'scheduled': return '#007bff';
    case 'completed': return '#28a745';
    case 'cancelled': return '#dc3545';
    default: return '#333';
  }
}

export default Appointments;

// src/components/normal_users/Appointments.jsx

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import styles from './Appointments.module.css';
import axios from 'axios';
import BASE_URL from '../../config/apiConfig';
import { toast } from 'react-toastify';
import StripePaymentModal from './StripePaymentModal';

const Appointments = () => {
  const [appointments, setAppointments] = useState([]);
  const [slots, setSlots] = useState([]);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('appointments');
  const navigate = useNavigate();

  // Payment Modal State
  const [paymentData, setPaymentData] = useState({
    clientSecret: null,
    publishableKey: null,
    amount: null,
    appointmentId: null,
  });

  const token = localStorage.getItem('accessToken');

  useEffect(() => {
    if (activeTab === 'appointments') {
      fetchAppointments();
    } else {
      fetchAvailableSlots();
    }
  }, [activeTab]);

  const fetchAppointments = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${BASE_URL}/user/appointments`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setAppointments(res.data.appointments || []);
    } catch (err) {
      console.error('Error fetching appointments:', err);
      toast.error('Failed to fetch appointments');
    } finally {
      setLoading(false);
    }
  };

  const fetchAvailableSlots = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${BASE_URL}/user/appointments/slots`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setSlots(res.data.slots || []);
    } catch (err) {
      console.error('Error fetching slots:', err);
      toast.error('Failed to fetch available slots');
    } finally {
      setLoading(false);
    }
  };

  const bookAppointment = async (slot) => {
    try {
      setLoading(true);
      // 1. Create Appointment
      const apptRes = await axios.post(`${BASE_URL}/user/appointments`, {
        counsellor_id: slot.counsellor_id,
        availability_slot_id: slot.availability_slot_id,
        reason: 'General Consultation'
      }, {
        headers: { Authorization: `Bearer ${token}` },
      });

      const appointmentId = apptRes.data.appointment_id || apptRes.data.id;

      // 2. Create Payment Intent
      if (appointmentId) {
        const intentRes = await axios.post(`${BASE_URL}/payments/create-intent`, {
          appointment_id: appointmentId,
          amount: 500.00,
          currency: "INR"
        }, {
          headers: { Authorization: `Bearer ${token}` }
        });

        const { client_secret, publishable_key, amount } = intentRes.data;

        // 3. Show Stripe Elements Modal
        setPaymentData({
          clientSecret: client_secret,
          publishableKey: publishable_key,
          amount: amount,
          appointmentId: appointmentId
        });
      } else {
        toast.success('Appointment booked successfully!');
        setActiveTab('appointments');
      }

    } catch (err) {
      console.error('Error booking appointment:', err);
      toast.error(err.response?.data?.detail || 'Failed to book appointment');
    } finally {
      setLoading(false);
    }
  };

  const handlePaymentSuccess = async () => {
    toast.success('Payment Successful! Appointment booked.');
    setPaymentData({ clientSecret: null, publishableKey: null, amount: null, appointmentId: null });
    setActiveTab('appointments');
    fetchAppointments();
  };

  const handlePaymentCancel = () => {
    toast.warning('Payment cancelled.');
    setPaymentData({ clientSecret: null, publishableKey: null, amount: null, appointmentId: null });
  };

  const cancelAppointment = async (appointmentId) => {
    if (!window.confirm("Are you sure you want to cancel this appointment?")) return;

    try {
      setLoading(true);
      await axios.patch(`${BASE_URL}/user/appointments/cancel/${appointmentId}`, null, {
        headers: { Authorization: `Bearer ${token}` },
        params: { reason: "User cancelled" }
      });
      toast.success('Appointment cancelled successfully!');
      fetchAppointments();
    } catch (err) {
      console.error('Error cancelling appointment:', err);
      toast.error('Failed to cancel appointment');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <h2 className={styles.heading}>Appointments Management</h2>

      <div className={styles.buttonGroup}>
        <button 
          className={activeTab === 'appointments' ? styles.button : styles.buttonOutline} 
          onClick={() => setActiveTab('appointments')}
        >
          My Appointments
        </button>
        <button 
          className={styles.buttonOutline} 
          onClick={() => navigate('/approved-counsellors')}
        >
          Book New Appointment
        </button>
      </div>

      {loading && <p className={styles.placeholderText}>Loading...</p>}

      {!loading && activeTab === 'appointments' && (
        <>
          {appointments.length > 0 ? (
            <div className={styles.cardGrid}>
              {appointments.map((appt) => (
                <div key={appt.appointment_id} className={styles.card}>
                  <h4 style={{marginBottom: 10, color: '#003fdd'}}>With Counsellor</h4>
                  <p><strong>Status:</strong> <span style={{color: appptStatusColor(appt.status)}}>{appt.status}</span></p>
                  <p><strong>Scheduled:</strong> {new Date(appt.session?.session_scheduled_at).toLocaleString()}</p>

                  {(appt.status === 'scheduled' || appt.status === 'confirmed') && (
                    <div style={{ marginTop: 15, display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                      <button 
                        onClick={() => navigate(`/counselling-session/${appt.session?.session_id}`)}
                        style={{ backgroundColor: '#003fdd', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer' }}
                      >
                        Join Call
                      </button>
                      <button 
                        onClick={() => {
                          const roomId = `chat_${appt.counsellor?.user_id}_${appt.user?.user_id}`;
                          navigate('/chat', { state: { selectedRoomId: roomId } });
                        }}
                        style={{ backgroundColor: '#28a745', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer' }}
                      >
                        Message
                      </button>
                    </div>
                  )}

                  {appt.status !== 'cancelled' && appt.status !== 'completed' && (
                    <button 
                      onClick={() => cancelAppointment(appt.appointment_id)}
                      style={{marginTop: 15, backgroundColor: '#dc3545', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer'}}
                    >
                      Cancel Appointment
                    </button>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <p className={styles.placeholderText}>You have no appointments yet.</p>
          )}
        </>
      )}

      {!loading && activeTab === 'slots' && (
        <>
          {slots.length > 0 ? (
            <div className={styles.cardGrid}>
              {slots.map((slot) => (
                <div key={slot.availability_slot_id} className={styles.card}>
                  <h4 style={{marginBottom: 10, color: '#003fdd'}}>Available Slot</h4>
                  <p><strong>Date:</strong> {new Date(slot.start_time).toLocaleDateString()}</p>
                  <p><strong>Time:</strong> {new Date(slot.start_time).toLocaleTimeString()} - {new Date(slot.end_time).toLocaleTimeString()}</p>

                  <button 
                    onClick={() => bookAppointment(slot)}
                    style={{marginTop: 15, backgroundColor: '#28a745', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer'}}
                  >
                    Book Slot
                  </button>
                </div>
              ))}
            </div>
          ) : (
            <p className={styles.placeholderText}>No available slots at the moment.</p>
          )}
        </>
      )}

      {/* Stripe Payment Modal */}
      {paymentData.clientSecret && (
        <StripePaymentModal
          clientSecret={paymentData.clientSecret}
          publishableKey={paymentData.publishableKey}
          amount={paymentData.amount}
          onSuccess={handlePaymentSuccess}
          onCancel={handlePaymentCancel}
        />
      )}
    </div>
  );
};

const appptStatusColor = (status) => {
  switch (status?.toLowerCase()) {
    case 'scheduled': return '#007bff';
    case 'completed': return '#28a745';
    case 'cancelled': return '#dc3545';
    default: return '#333';
  }
}

export default Appointments;

