import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axiosInstance from '../../utils/axiosInstance';
import { toast } from 'react-toastify';

const AppointmentsList = () => {
  const navigate = useNavigate();
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('upcoming'); // upcoming, past, all

  useEffect(() => {
    fetchAppointments();
  }, [filter]);

  const fetchAppointments = async () => {
    try {
      setLoading(true);
      const res = await axiosInstance.get('/user/appointments', {
        params: {
          upcoming: filter === 'upcoming' ? true : (filter === 'past' ? false : undefined)
        }
      });
      setAppointments(res.data.appointments || []);
    } catch (err) {
      console.error('Failed to load appointments', err);
      toast.error('Could not load appointments');
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async (appointmentId) => {
    if (!window.confirm("Are you sure you want to cancel this appointment?")) return;

    try {
      await axiosInstance.patch(`/user/appointments/cancel/${appointmentId}`, null, {
        params: { reason: "User requested cancellation" }
      });
      toast.success('Appointment cancelled successfully');
      fetchAppointments();
    } catch (err) {
      console.error('Failed to cancel appointment', err);
      toast.error(err.response?.data?.detail || 'Failed to cancel appointment');
    }
  };

  return (
    <div className="max-w-6xl mx-auto py-8 flex flex-col min-h-screen">
      <div className="flex justify-between items-center mb-8 border-b border-outline pb-6">
        <h1 className="font-display-lg text-headline-lg font-bold text-ink-black">My Appointments</h1>

        <div className="flex gap-4">
          <button 
            onClick={() => setFilter('upcoming')}
            className={`px-6 py-2 rounded-xl border-outline font-label-bold transition-all ${filter === 'upcoming' ? 'bg-primary text-white shadow-subtle' : 'bg-white text-ink-black hover:bg-surface-container'}`}
          >
            Upcoming
          </button>
          <button 
            onClick={() => setFilter('past')}
            className={`px-6 py-2 rounded-xl border-outline font-label-bold transition-all ${filter === 'past' ? 'bg-primary text-white shadow-subtle' : 'bg-white text-ink-black hover:bg-surface-container'}`}
          >
            Past
          </button>
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center items-center h-40"><span className="material-symbols-outlined animate-spin text-4xl text-primary">autorenew</span></div>
      ) : appointments.length === 0 ? (
        <div className="bg-white border-outline rounded-xl p-12 text-center shadow-subtle">
          <span className="material-symbols-outlined text-6xl text-on-surface-variant mb-4">calendar_month</span>
          <h2 className="font-headline-md text-ink-black mb-2">No {filter} appointments</h2>
          <p className="font-body-md text-on-surface-variant mb-6">You don't have any {filter} appointments scheduled right now.</p>
          <button
            onClick={() => navigate('/counsellors')}
            className="bg-primary text-white px-6 py-2.5 rounded-xl font-label-bold"
          >
            Find a Counsellor
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {appointments.map(app => {
            const isCancelled = app.status === 'cancelled';
            const dateStr = app.session?.session_scheduled_at ? new Date(app.session.session_scheduled_at).toLocaleString() : 'Scheduled';
            const sessionId = app.session?.session_id;

            return (
              <div key={app.appointment_id} className={`bg-white border-outline rounded-xl p-6 ${isCancelled ? 'opacity-60' : 'shadow-subtle'} flex flex-col`}>
                <div className="flex justify-between items-start mb-4">
                  <div className={`px-3 py-1 rounded-full border-outline font-label-bold text-xs ${isCancelled ? 'bg-surface-container-low text-ink-black' : 'bg-accent-sage text-ink-black'}`}>
                    {app.status.toUpperCase()}
