export default AppointmentsList;

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, useParams } from 'react-router-dom';
import axiosInstance from '../../utils/axiosInstance';
import { toast } from 'react-toastify';

const BookingSlot = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { id } = useParams();
  const counsellorId = location.state?.counsellorId || id;
  const bookingType = location.state?.bookingType;

  const [counsellor, setCounsellor] = useState(null);

  // Date and slot selection
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [availableSlots, setAvailableSlots] = useState([]);
  const [selectedSlot, setSelectedSlot] = useState(null);
  const [loadingSlots, setLoadingSlots] = useState(false);

  // Generate next 14 days
  const [dates, setDates] = useState([]);

  useEffect(() => {
    if (!counsellorId) {
      navigate(-1);
      return;
    }

    // Generate dates
    const generatedDates = [];
    for (let i = 0; i < 14; i++) {
      const d = new Date();
      d.setDate(d.getDate() + i);
      generatedDates.push(d);
    }
    setDates(generatedDates);
    setSelectedDate(generatedDates[0]);

    // Fetch counsellor
    const fetchCounsellor = async () => {
      try {
        const res = await axiosInstance.get(`/content/counsellors/${counsellorId}`);
        setCounsellor(res.data);
      } catch (err) {
        console.error('Failed to load counsellor', err);
        toast.error('Could not load counsellor profile');
      }
    };
    fetchCounsellor();
  }, [counsellorId, navigate]);

  useEffect(() => {
    if (counsellorId && selectedDate) {
      fetchSlots();
    }
  }, [counsellorId, selectedDate]);

  const fetchSlots = async () => {
    try {
      setLoadingSlots(true);
      const res = await axiosInstance.get('/user/appointments/slots', {
        params: {
          counsellor_id: counsellorId,
          date: selectedDate.toISOString()
        }
      });
      setAvailableSlots((res.data.slots || []).map(slot => ({ ...slot, id: slot.availability_slot_id })));
      setSelectedSlot(null);
    } catch (err) {
      console.error('Failed to load slots', err);
      setAvailableSlots([]);
    } finally {
      setLoadingSlots(false);
    }
  };

  const handleConfirm = () => {
    if (!selectedSlot) {
      toast.error('Please select a time slot.');
      return;
    }

    navigate('/booking/payment', {
      state: {
        counsellorId,
        bookingType,
        selectedDate: selectedDate.toISOString(),
        selectedSlot
      }
    });
  };

  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  // Group slots
  const morningSlots = availableSlots.filter(s => {
    const hour = new Date(s.start_time).getHours();
    return hour < 12;
  });

  const afternoonSlots = availableSlots.filter(s => {
    const hour = new Date(s.start_time).getHours();
    return hour >= 12 && hour < 17;
  });

  const eveningSlots = availableSlots.filter(s => {
    const hour = new Date(s.start_time).getHours();
    return hour >= 17;
  });

  return (
    <div className="max-w-6xl mx-auto py-8 flex flex-col min-h-[calc(100vh-8rem)] relative pb-32">


      <div className="flex justify-between items-center mb-8">
        <h2 className="font-headline-sm text-headline-sm text-ink-black">Book a Session</h2>
      </div>

      {counsellor && (
        <div className="mb-8 bg-white border-outline rounded-xl p-8 flex flex-col md:flex-row items-center gap-10">
          <div className="relative w-40 h-40 shrink-0">
            <div className="absolute inset-0 bg-surface rounded-xl border-outline -"></div>
            <div className="relative w-full h-full rounded-xl border-outline overflow-hidden bg-white flex items-center justify-center font-bold text-4xl text-ink-black">
              {counsellor.profile_pic ? (
                <img alt="Therapist" className="w-full h-full object-cover" src={counsellor.profile_pic} />
              ) : (
                counsellor.name.charAt(0)
              )}
            </div>
          </div>
          <div className="flex-grow">
            <div className="flex items-center gap-4 mb-2">
              <h2 className="font-headline-md text-headline-md">{counsellor.name}</h2>
              {counsellor.is_featured && <span className="bg-accent-sage px-3 py-1 rounded-full border-[1px] border-outline font-label-md text-label-md">Top Rated</span>}
            </div>
            <p className="font-body-lg text-body-lg text-on-surface-variant mb-4">{counsellor.bio || 'Clinical Psychologist'}</p>
            <div className="flex flex-wrap gap-6">
              <div className="flex items-center gap-2">
                <span className="material-symbols-outlined text-secondary" style={{ fontVariationSettings: "'FILL' 1" }}>star</span>
                <span className="font-label-bold text-label-bold">{counsellor.average_rating} ({counsellor.total_reviews} Reviews)</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="material-symbols-outlined text-primary">schedule</span>
                <span className="font-label-bold text-label-bold">{counsellor.session_duration || 50} min Session</span>
              </div>
            </div>
          </div>
          <div className="bg-surface-container rounded-xl p-6 border-outline flex flex-col items-center justify-center text-center shrink-0">
            <span className="font-label-md text-label-md text-on-surface-variant uppercase tracking-wider">Fee</span>
            <span className="font-headline-md text-headline-md font-bold text-primary">₹{counsellor.session_fee}</span>
            <span className="font-label-md text-label-md text-on-surface-variant">per session</span>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2">
          <div className="bg-white border-outline rounded-xl p-8 h-full">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-headline-sm text-headline-sm">Select Date</h3>
            </div>

            <div className="grid grid-cols-7 gap-4">
              {days.map(d => (
                <div key={d} className="text-center font-label-bold text-label-bold text-on-surface-variant">{d}</div>
              ))}

              {/* Padding for first day of week */}
              {dates.length > 0 && Array.from({ length: dates[0].getDay() }).map((_, i) => (
                 <div key={'pad'+i} />
              ))}

              {dates.map((d, i) => {
                const isSelected = selectedDate && selectedDate.toDateString() === d.toDateString();
                const isToday = new Date().toDateString() === d.toDateString();

                return (
                  <div 
                    key={i} 
                    onClick={() => setSelectedDate(d)}
                    className={`aspect-square flex flex-col items-center justify-center border-outline rounded-2xl cursor-pointer hover:bg-accent-sage transition-all ${isSelected ? 'date-selected' : ''}`}
                  >
                    <span className={isSelected ? 'font-label-bold text-label-bold' : 'font-label-md text-label-md'}>{d.getDate()}</span>
                    {isToday && <span className="text-[10px] uppercase font-bold mt-1">Today</span>}
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        <div className="lg:col-span-1">
          <div className="bg-white border-outline rounded-xl p-8 flex flex-col h-full">
            <h3 className="font-headline-sm text-headline-sm mb-6">Select Time</h3>

            {loadingSlots ? (
              <div className="flex justify-center items-center h-40"><span className="material-symbols-outlined animate-spin text-4xl text-primary">autorenew</span></div>
            ) : availableSlots.length === 0 ? (
              <div className="text-center text-on-surface-variant my-auto">No slots available for this date.</div>
            ) : (
              <div className="flex-grow overflow-y-auto pr-2 space-y-8">
                {morningSlots.length > 0 && (
                  <div>
                    <div className="flex items-center gap-2 mb-4 text-on-surface-variant">
                      <span className="material-symbols-outlined">wb_sunny</span>
                      <span className="font-label-bold text-label-bold uppercase tracking-wider">Morning</span>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      {morningSlots.map((s, i) => (
                        <button 
                          key={i} 
                          onClick={() => !s.is_booked && setSelectedSlot(s)}
                          className={`py-3 px-4 rounded-xl border-outline text-center transition-all ${s.is_booked ? 'bg-surface-container-low opacity-40 cursor-not-allowed line-through' : selectedSlot?.id === s.id ? 'slot-selected' : 'hover:bg-secondary-container'}`}
                        >
                          {s.start_time.substring(0, 5)}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {afternoonSlots.length > 0 && (
                  <div>
                    <div className="flex items-center gap-2 mb-4 text-on-surface-variant">
                      <span className="material-symbols-outlined">light_mode</span>
                      <span className="font-label-bold text-label-bold uppercase tracking-wider">Afternoon</span>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      {afternoonSlots.map((s, i) => (
                        <button 
                          key={i} 
                          onClick={() => !s.is_booked && setSelectedSlot(s)}
                          className={`py-3 px-4 rounded-xl border-outline text-center transition-all ${s.is_booked ? 'bg-surface-container-low opacity-40 cursor-not-allowed line-through' : selectedSlot?.id === s.id ? 'slot-selected' : 'hover:bg-secondary-container'}`}
                        >
                          {s.start_time.substring(0, 5)}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {eveningSlots.length > 0 && (
                  <div>
                    <div className="flex items-center gap-2 mb-4 text-on-surface-variant">
                      <span className="material-symbols-outlined">dark_mode</span>
                      <span className="font-label-bold text-label-bold uppercase tracking-wider">Evening</span>
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      {eveningSlots.map((s, i) => (
                        <button 
                          key={i} 
                          onClick={() => !s.is_booked && setSelectedSlot(s)}
                          className={`py-3 px-4 rounded-xl border-outline text-center transition-all ${s.is_booked ? 'bg-surface-container-low opacity-40 cursor-not-allowed line-through' : selectedSlot?.id === s.id ? 'slot-selected' : 'hover:bg-secondary-container'}`}
                        >
                          {s.start_time.substring(0, 5)}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 md:left-64 right-0 p-8 bg-white/80 backdrop-blur-md border-t-[1.5px] border-outline flex justify-between items-center z-20">
        <div className="flex flex-col">
          <span className="font-label-md text-label-md text-on-surface-variant">Selected Appointment</span>
          <span className="font-label-bold text-label-bold text-ink-black">
            {selectedDate.toDateString()} {selectedSlot ? `at ${selectedSlot.start_time.substring(0, 5)}` : '--:--'}
          </span>
        </div>
        <div className="flex gap-4">
          <button onClick={() => navigate(-1)} className="px-8 py-4 bg-white text-ink-black font-label-bold text-label-bold rounded-xl border-outline hover:bg-surface-container transition-all active:scale-[0.98]">
            Cancel
          </button>
          <button 
            onClick={handleConfirm}
            className="px-12 py-4 bg-primary text-white font-label-bold text-label-bold rounded-xl border-outline shadow-subtle hover:translate-x-1 hover:translate-y-1 hover:shadow-none active:scale-[0.98] transition-all flex items-center gap-2"
          >
            Confirm Appointment
            <span className="material-symbols-outlined">arrow_forward</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default BookingSlot;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import axiosInstance from '../../utils/axiosInstance';

const GroupChat = () => {
  const navigate = useNavigate();
  const { groupId } = useParams();
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(true);

  const [messages, setMessages] = useState([
    {
      id: 1,
      sender: 'Anonymous Bear',
      time: '10:42 AM',
      content: "Hey everyone. I'm feeling a bit overwhelmed today. The breathing exercises we discussed yesterday aren't really helping.",
      isSelf: false,
      avatar: 'pets',
      color: 'bg-accent-sage',
      iconColor: 'text-outline-variant',
      reactions: []
    },
    {
      id: 2,
      sender: 'Calm River',
      time: '10:45 AM',
      content: "I've been there, Bear. Sometimes focusing on the breath just makes me more anxious. Have you tried grounding with the 5-4-3-2-1 method instead?",
      isSelf: false,
      avatar: 'water_drop',
      color: 'bg-tertiary-fixed',
      iconColor: 'text-tertiary',
      reactions: [{ emoji: '<span className="material-symbols-outlined text-sm text-rose-text">favorite</span>️', count: 3 }]
    },
    {
      id: 3,
      sender: 'You',
      time: '10:48 AM',
      content: "The 5-4-3-2-1 method is great. If that feels like too much right now, maybe just try holding something cold? An ice cube or a cold glass of water works wonders for snapping out of a spiral.",
      isSelf: true,
      avatar: 'person',
      color: 'bg-primary-fixed',
      iconColor: 'text-primary',
      reactions: []
    }
  ]);

  useEffect(() => {
    fetchFeed();
  }, [groupId]);

  const fetchFeed = async () => {
    try {
      const res = await axiosInstance.get(`/community/groups/${groupId}/feed`);
      setMessages(res.data.map(p => ({
        id: p.id,
        sender: p.is_anonymous ? 'Anonymous' : 'User',
        time: new Date(p.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        content: p.content,
        isSelf: p.user_id === localStorage.getItem('userId'), // We might not have userId in localstorage exactly, assume false for now if not matching
        avatar: 'person',
        color: 'bg-accent-sage',
        iconColor: 'text-outline-variant',
        reactions: []
      })));
    } catch (err) {
      console.error('Failed to load group feed', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSend = async () => {
    if (message.trim()) {
      try {
        await axiosInstance.post('/community/posts', {
          content: message,
          is_anonymous: false,
          has_trigger_warning: false,
          group_id: groupId
        });
        setMessage('');
        fetchFeed();
      } catch (err) {
        console.error('Failed to send message', err);
      }
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  if (loading) return <p role="status">Loading the group conversation?</p>;
  return (
    <div className="flex-1 flex flex-col h-[calc(100vh-80px)] bg-background">
      
      
      {/* Chat Header */}
      <div className="px-4 md:px-margin-desktop py-4 border-b border-outline bg-surface-bright flex items-center justify-between shrink-0 sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/community/groups')} className="md:hidden p-2 text-on-surface hover:bg-surface-container rounded-full">
            <span className="material-symbols-outlined">arrow_back</span>
          </button>
          <div className="w-14 h-14 rounded-2xl bg-surface neo-border shadow-subtle flex items-center justify-center rotate-[-3deg] shrink-0">
            <span className="material-symbols-outlined text-3xl" style={{ fontVariationSettings: "'FILL' 1" }}>self_improvement</span>
          </div>
          <div>
            <h2 className="font-headline-sm text-headline-sm text-ink-black flex items-center gap-2 flex-wrap">
              Mindful Circle
              <span className="px-2 py-0.5 rounded-full border-outline bg-secondary-container text-on-secondary-container text-xs font-label-bold">Verified</span>
            </h2>
            <p className="font-body-md text-body-md text-on-surface-variant flex items-center gap-1">
              <span className="w-2 h-2 rounded-full bg-green-500 neo-border"></span>
              124 members online
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2 md:gap-3">
          <button className="p-2 rounded-xl border-outline bg-surface hover:bg-accent-sage transition-colors">
            <span className="material-symbols-outlined">search</span>
          </button>
          <button className="p-2 rounded-xl border-outline bg-surface hover:bg-accent-sage transition-colors">
            <span className="material-symbols-outlined">more_vert</span>
          </button>
        </div>
      </div>

      {/* Chat Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 md:p-margin-desktop flex flex-col gap-6">
        
        {/* Date Divider */}
        <div className="flex justify-center my-4">
          <span className="px-4 py-1 rounded-full border-outline bg-surface-variant text-on-surface-variant font-label-bold text-label-bold text-xs">Today</span>
        </div>

        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-start gap-4 max-w-2xl ${msg.isSelf ? 'self-end flex-row-reverse' : ''}`}>
            <div className={`w-10 h-10 rounded-full ${msg.color} neo-border flex items-center justify-center shrink-0`}>
              <span className={`material-symbols-outlined ${msg.iconColor}`}>{msg.avatar}</span>
            </div>
            
            <div className={`flex flex-col gap-1 ${msg.isSelf ? 'items-end' : ''}`}>
              <div className={`flex items-baseline gap-2 ${msg.isSelf ? 'flex-row-reverse' : ''}`}>
                <span className="font-label-bold text-label-bold text-ink-black">{msg.sender}</span>
                <span className="text-xs text-on-surface-variant">{msg.time}</span>
              </div>
              
              <div className={`${msg.isSelf ? 'bg-primary-fixed text-on-surface rounded-tr-sm' : 'bg-surface text-ink-black rounded-tl-sm'} border-outline rounded-2xl p-4 shadow-subtle`}>
                <p className="font-body-lg text-body-lg">{msg.content}</p>
              </div>
              
              {/* Reactions */}
              {msg.reactions && msg.reactions.length > 0 && (
                <div className={`flex gap-2 mt-1 ${msg.isSelf ? 'justify-end' : ''}`}>
                  {msg.reactions.map((r, i) => (
                    <button key={i} className="px-2 py-1 rounded-full border-outline bg-secondary-fixed text-sm flex items-center gap-1 hover:bg-secondary-fixed-dim transition-colors">
                      {r.emoji} <span className="font-label-bold">{r.count}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}
        
        {/* System Message */}
        <div className="flex justify-center my-6">
          <div className="flex items-center gap-2 bg-accent-sage/30 px-4 py-2 rounded-full border-dashed border-outline-variant">
            <span className="material-symbols-outlined text-sm text-outline-variant">campaign</span>
            <span className="font-label-md text-label-md text-on-surface-variant text-center">Reminder: Group meditation starts in 15 minutes.</span>
          </div>
        </div>
        
        {/* Typing indicator (hardcoded) */}
        <div className="flex items-start gap-4 max-w-2xl">
          <div className="w-10 h-10 rounded-full bg-accent-sage neo-border flex items-center justify-center shrink-0">
            <span className="material-symbols-outlined text-outline-variant">pets</span>
          </div>
          <div className="flex flex-col gap-1">
            <div className="flex items-baseline gap-2">
              <span className="font-label-bold text-label-bold text-ink-black">Anonymous Bear</span>
            </div>
            <div className="bg-surface border-outline rounded-2xl rounded-tl-sm p-4 shadow-subtle flex items-center gap-1 w-16">
              <div className="w-2 h-2 bg-outline rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
              <div className="w-2 h-2 bg-outline rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
              <div className="w-2 h-2 bg-outline rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
            </div>
          </div>
        </div>
        
        <div className="h-4"></div>
      </div>
      
      {/* Input Area */}
      <div className="px-4 md:px-margin-desktop pb-4 md:pb-margin-desktop pt-4 bg-background shrink-0">
        
        {/* Quick Replies */}
        <div className="flex gap-3 mb-4 overflow-x-auto scrollbar-hide pb-2">
          {['"I hear you."', '"Take your time."', '"You\'re not alone in this."'].map((reply, i) => (
            <button 
              key={i}
              onClick={() => setMessage(reply.replace(/"/g, ''))}
              className="shrink-0 px-4 py-2 rounded-full border-outline bg-surface hover:bg-accent-sage transition-colors font-label-md text-label-md"
            >
              {reply}
            </button>
          ))}
        </div>
        
        {/* Input Bar */}
        <div className="flex items-end gap-2 md:gap-4 bg-surface border-outline rounded-2xl p-2 shadow-subtle focus-within:shadow-subtle focus-within:translate-x-[2px] focus-within:translate-y-[2px] transition-all">
          <button className="p-2 md:p-3 text-outline hover:text-primary transition-colors shrink-0">
            <span className="material-symbols-outlined">add_circle</span>
          </button>
          
          <textarea 
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            onKeyPress={handleKeyPress}
            className="flex-1 bg-transparent border-none focus:ring-0 resize-none py-3 font-body-md text-body-md max-h-32 overflow-y-auto" 
            placeholder="Share your thoughts anonymously..." 
            rows="1"
            style={{ height: 'auto' }}
          ></textarea>
          
          <div className="flex items-center gap-1 md:gap-2 shrink-0 pr-1 md:pr-2 pb-1">
            <button className="hidden sm:block p-2 text-outline hover:text-primary transition-colors">
              <span className="material-symbols-outlined">mood</span>
            </button>
            <button 
              onClick={handleSend}
              disabled={!message.trim()}
              className="p-2 bg-primary text-on-primary rounded-xl border-outline hover:bg-primary-container transition-colors flex items-center justify-center disabled:opacity-50"
            >
              <span className="material-symbols-outlined">send</span>
            </button>
          </div>
        </div>
        <p className="text-center text-xs text-outline-variant mt-3 hidden md:block">Messages are anonymous and end-to-end encrypted.</p>
      </div>
    </div>
  );
};

export default GroupChat;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axiosInstance from '../../utils/axiosInstance';
import { toast } from 'react-toastify';

const EditProfile = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [profileData, setProfileData] = useState({
    name: '',
    email: '',
    phone_number: '',
    bio: '',
  });

  const userType = localStorage.getItem('userType');
  const endpoint = userType === 'admin' ? '/admin/dashboard/profile' : userType === 'counsellor' ? '/counsellor/dashboard/profile' : '/user/dashboard/profile';

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      setLoading(true);
      const res = await axiosInstance.get(endpoint);
      setProfileData({
        name: res.data.name || '',
        email: res.data.email || '',
        phone_number: res.data.phone_number || '',
        bio: res.data.bio || '', // bio might not exist on all models, gracefully fallback
      });
    } catch (err) {
      console.error('Failed to load profile', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async (e) => {
    e.preventDefault();
    try {
      setSaving(true);
      const payload = new FormData();
      for (const key of ['name', 'phone_number', 'bio']) payload.append(key, profileData[key] || '');
      await axiosInstance.patch(endpoint, payload);
      toast.success('Profile updated successfully');
      navigate('/profile');
    } catch (err) {
      console.error('Failed to update profile', err);
    } finally {
      setSaving(false);
    }
  };

  const handleCancel = () => {
    navigate('/profile');
  };

  if (loading) {
    return <div className="flex items-center justify-center min-h-[50vh]"><span className="material-symbols-outlined animate-spin text-4xl text-primary">autorenew</span></div>;
  }

  return (
    <div className="flex-1 py-12 px-6 md:px-10 max-w-4xl mx-auto w-full">
      

      <div className="mb-12">
        <h2 className="font-headline-md text-3xl font-bold text-ink-black">Edit Profile</h2>
        <p className="text-on-surface-variant font-body-lg">Keep your information up to date to get the best experience.</p>
      </div>

      <div className="bg-white border-outline rounded-xl p-8 md:p-12 relative overflow-hidden shadow-subtle">
        <div className="flex flex-col items-center mb-12">
          <div className="relative group cursor-pointer">
            <div className="w-32 h-32 rounded-full border-outline overflow-hidden bg-surface flex items-center justify-center text-4xl font-bold text-ink-black">
              {profileData.name ? profileData.name.charAt(0).toUpperCase() : 'U'}
            </div>
            <div className="absolute bottom-0 right-0 w-10 h-10 bg-primary text-white rounded-full border-outline flex items-center justify-center shadow-subtle hover:-translate-x-0.5 hover:-translate-y-0.5 active:translate-x-0.5 active:translate-y-0.5 active:shadow-none transition-all">
              <span className="material-symbols-outlined text-[20px]">photo_camera</span>
            </div>
          </div>
          <p className="mt-4 font-label-bold text-label-bold text-primary cursor-pointer hover:underline">Change Profile Picture</p>
        </div>

        <form className="space-y-8" onSubmit={handleSave}>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="font-label-bold text-label-bold text-on-surface block" htmlFor="full-name">Full Name</label>
              <input 
                id="full-name" 
                type="text" 
                className="w-full bg-[#f9f8f3] border-outline rounded-xl px-4 py-3 text-body-md transition-all focus:ring-0 focus:border-primary focus:shadow-subtle" 
                value={profileData.name}
                onChange={(e) => setProfileData({...profileData, name: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="font-label-bold text-label-bold text-on-surface block" htmlFor="email">Email Address</label>
              <input 
                id="email" 
                type="email" 
                disabled
                className="w-full bg-[#e4e1e8] border-outline rounded-xl px-4 py-3 text-body-md transition-all opacity-70 cursor-not-allowed" 
                value={profileData.email}
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="font-label-bold text-label-bold text-on-surface block" htmlFor="phone">Phone Number</label>
              <input 
                id="phone" 
                type="tel" 
                className="w-full bg-[#f9f8f3] border-outline rounded-xl px-4 py-3 text-body-md transition-all focus:ring-0 focus:border-primary focus:shadow-subtle" 
                value={profileData.phone_number}
                onChange={(e) => setProfileData({...profileData, phone_number: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="font-label-bold text-label-bold text-on-surface block" htmlFor="timezone">Timezone</label>
              <select className="w-full bg-[#f9f8f3] border-outline rounded-xl px-4 py-3 text-body-md focus:ring-0 focus:border-primary focus:shadow-subtle" id="timezone">
                <option>Pacific Time (PT)</option>
                <option>Eastern Time (ET)</option>
                <option>Greenwich Mean Time (GMT)</option>
              </select>
            </div>
          </div>

          {userType === 'counsellor' && (
            <div className="space-y-2">
              <div className="flex justify-between items-center">
                <label className="font-label-bold text-label-bold text-on-surface block" htmlFor="bio">Bio</label>
                <span className="text-label-md text-on-surface-variant">{profileData.bio?.length || 0} / 300</span>
              </div>
              <textarea 
                id="bio" 
                rows="4" 
                maxLength="300"
                className="w-full bg-[#f9f8f3] border-outline rounded-xl px-4 py-3 text-body-md transition-all resize-none focus:ring-0 focus:border-primary focus:shadow-subtle" 
                value={profileData.bio}
                onChange={(e) => setProfileData({...profileData, bio: e.target.value})}
                placeholder="Tell us about yourself..."
              ></textarea>
            </div>
          )}

          <div className="flex flex-col md:flex-row items-center gap-6 pt-6">
            <button 
              type="submit" 
              disabled={saving}
              className="w-full md:w-auto px-10 py-3 bg-primary text-white border-outline shadow-subtle font-bold rounded-xl active:scale-[0.98] transition-all disabled:opacity-70"
            >
              {saving ? 'Saving...' : 'Save Changes'}
            </button>
            <button 
              type="button" 
              onClick={handleCancel}
              className="w-full md:w-auto px-10 py-3 bg-accent-sage text-ink-black border-outline font-bold rounded-xl hover:bg-surface-variant transition-colors active:translate-x-0.5 active:translate-y-0.5"
            >
              Discard Edits
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default EditProfile;
